import{_ as e,C as i,c as n,o as t,a0 as a,b as l,w as o,a as r,G as d,a1 as s}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Teamcommunicatie","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/team-player/communication.md","filePath":"nl/education/team-player/communication.md"}');const c=e({name:"nl/education/team-player/communication.md"},[["render",function(e,u,c,m,h,g){const k=i("Mermaid");return t(),n("div",null,[u[1]||(u[1]=a('<h1 id="teamcommunicatie" tabindex="-1">Teamcommunicatie <a class="header-anchor" href="#teamcommunicatie" aria-label="Permalink to &quot;Teamcommunicatie&quot;">​</a></h1><p>Effectieve communicatie is wat een groep individuen in een team verandert. Bij pétanque, waar de strategie voortdurend verandert en de druk hoog is, kan de manier waarop je communiceert de uitkomst bepalen.</p><div class="tip custom-block"><p class="custom-block-title">Het Grote Idee</p><p><strong>Communicatie is wat individuen in een team verandert.</strong> Duidelijke, specifieke en ondersteunende communicatie onder druk onderscheidt goede teams van geweldige teams.</p></div><h2 id="de-communicatiecyclus" tabindex="-1">De communicatiecyclus <a class="header-anchor" href="#de-communicatiecyclus" aria-label="Permalink to &quot;De communicatiecyclus&quot;">​</a></h2><p>Goede teamcommunicatie volgt een cyclus:</p>',5)),(t(),l(s,null,{default:o(()=>[d(k,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObserveren%5D%20--%3E%20B%5BDeel%5D%0A%20%20%20%20B%20--%3E%20C%5BBespreken%5D%0A%20%20%20%20C%20--%3E%20D%5BBeslissen%5D%0A%20%20%20%20D%20--%3E%20E%5BUitvoeren%5D%0A%20%20%20%20E%20--%3E%20F%5BBeoordeling%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:o(()=>[...u[0]||(u[0]=[r(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=a('<table tabindex="0"><thead><tr><th>Stap</th><th>Actie</th><th>Voorbeeld</th></tr></thead><tbody><tr><td><strong>Observeer</strong></td><td>Let op wat er gebeurt.</td><td>Terrein, posities, tegenstanders</td></tr><tr><td><strong>Deel</strong></td><td>Vertel je teamgenoten wat je ziet.</td><td>&quot;De grond loopt daar schuin naar links af.&quot;</td></tr><tr><td><strong>Bespreken</strong></td><td>Wissel perspectieven uit</td><td>&quot;Moet ik blokkeren of voor het punt gaan?&quot;</td></tr><tr><td><strong>Beslissen</strong></td><td>Overeenstemming bereiken over de aanpak</td><td>&quot;Laten we de hoge lob eens proberen.&quot;</td></tr><tr><td><strong>Uitvoeren</strong></td><td>Doe het met toewijding.</td><td>Volledige concentratie op de worp</td></tr><tr><td><strong>Beoordeling</strong></td><td>Leer van het resultaat</td><td>&quot;Dat werkte prima&quot; of &quot;Volgende keer...&quot;</td></tr></tbody></table><h2 id="wanneer-te-communiceren" tabindex="-1">Wanneer te communiceren <a class="header-anchor" href="#wanneer-te-communiceren" aria-label="Permalink to &quot;Wanneer te communiceren&quot;">​</a></h2><h3 id="voor-elk-einde" tabindex="-1">Voor elk einde <a class="header-anchor" href="#voor-elk-einde" aria-label="Permalink to &quot;Voor elk einde&quot;">​</a></h3><ul><li>Beoordeel samen het terrein.</li><li>Bespreek de algemene aanpak.</li><li>Maak duidelijk wie er wanneer gooit.</li><li>Zet de toon (rustig, geconcentreerd)</li></ul><h3 id="tijdens-het-einde" tabindex="-1">Tijdens het einde <a class="header-anchor" href="#tijdens-het-einde" aria-label="Permalink to &quot;Tijdens het einde&quot;">​</a></h3><ul><li>Deel observaties (&quot;De grond helt daar naar links af&quot;)</li><li>Coördineer de strategie (&quot;Moet ik proberen te blokkeren of voor het punt gaan?&quot;)</li><li>Bied steun (&quot;Neem de tijd, je kunt dit&quot;).</li><li>Pas plannen aan naarmate de situatie verandert.</li></ul><h3 id="tussen-de-uiteinden" tabindex="-1">Tussen de uiteinden <a class="header-anchor" href="#tussen-de-uiteinden" aria-label="Permalink to &quot;Tussen de uiteinden&quot;">​</a></h3><ul><li>Korte nabespreking (wat werkte, wat niet)</li><li>Mentale reset</li><li>Bereid je voor op het volgende einde</li><li>Blijf als team in contact.</li></ul><h3 id="na-de-wedstrijd" tabindex="-1">Na de wedstrijd <a class="header-anchor" href="#na-de-wedstrijd" aria-label="Permalink to &quot;Na de wedstrijd&quot;">​</a></h3><ul><li>Uitgebreide nabespreking (indien van toepassing)</li><li>Erken de bijdragen</li><li>Identificeer leerpunten</li><li>Onderhoud de relatie</li></ul><h2 id="hoe-te-communiceren" tabindex="-1">Hoe te communiceren <a class="header-anchor" href="#hoe-te-communiceren" aria-label="Permalink to &quot;Hoe te communiceren&quot;">​</a></h2><h3 id="wees-duidelijk-en-specifiek" tabindex="-1">Wees duidelijk en specifiek. <a class="header-anchor" href="#wees-duidelijk-en-specifiek" aria-label="Permalink to &quot;Wees duidelijk en specifiek.&quot;">​</a></h3><p><strong>Vage omschrijving:</strong> &quot;Probeer dichterbij te komen&quot; <strong>Clear:</strong> &quot;Richt op de linkerkant van de jack, ongeveer 20 cm naar buiten&quot;</p><p><strong>Vage opmerking:</strong> &quot;Goed geprobeerd&quot; <strong>Duidelijk:</strong> &quot;Goed gewicht, net iets links van de lijn&quot;</p><h3 id="wees-constructief" tabindex="-1">Wees constructief <a class="header-anchor" href="#wees-constructief" aria-label="Permalink to &quot;Wees constructief&quot;">​</a></h3><p>Focus op oplossingen, niet op problemen:</p><p><strong>Probleemgericht:</strong> &quot;Je schiet steeds naar rechts naast&quot; <strong>Oplossingsgericht:</strong> &quot;Misschien iets meer naar links mikken om dat te compenseren?&quot;</p><h3 id="wees-ondersteunend" tabindex="-1">Wees ondersteunend <a class="header-anchor" href="#wees-ondersteunend" aria-label="Permalink to &quot;Wees ondersteunend&quot;">​</a></h3><p>Je toon is net zo belangrijk als je woorden:</p><ul><li>Blijf kalm, zelfs als je gefrustreerd bent.</li><li>Gebruik aanmoedigende lichaamstaal.</li><li>Erken de inspanning, niet alleen de resultaten.</li><li>Bouw op, breek niet af.</li></ul><h3 id="luister-aandachtig" tabindex="-1">Luister aandachtig <a class="header-anchor" href="#luister-aandachtig" aria-label="Permalink to &quot;Luister aandachtig&quot;">​</a></h3><p>Communicatie is een tweewegsverkeer:</p><ul><li>Luister aandachtig wanneer teamgenoten spreken.</li><li>Stel verduidelijkende vragen.</li><li>Erken wat je hebt gehoord.</li><li>Niet onderbreken of afwijzen.</li></ul><h2 id="communicatie-uitdagingen" tabindex="-1">Communicatie-uitdagingen <a class="header-anchor" href="#communicatie-uitdagingen" aria-label="Permalink to &quot;Communicatie-uitdagingen&quot;">​</a></h2><h3 id="meningsverschil-over-de-strategie" tabindex="-1">Meningsverschil over de strategie <a class="header-anchor" href="#meningsverschil-over-de-strategie" aria-label="Permalink to &quot;Meningsverschil over de strategie&quot;">​</a></h3><p><strong>Slechte aanpak:</strong></p><ul><li>Sta erop dat je je eigen weg volgt.</li><li>Ga de verdediging in</li><li>Geef met tegenzin toe</li><li>Ruzie maken tijdens het spel</li></ul><p><strong>Betere aanpak:</strong></p><ol><li>Deel je perspectief duidelijk.</li><li>Luister volledig naar die van hen.</li><li>Bespreek de voor- en nadelen kort.</li><li>Neem gezamenlijk een besluit (of laat de beslissing over aan de aangewezen leider).</li><li>Ga volledig achter de beslissing staan.</li><li>Nabespreking na de wedstrijd</li></ol><h3 id="na-een-fout-van-een-teamgenoot" tabindex="-1">Na een fout van een teamgenoot <a class="header-anchor" href="#na-een-fout-van-een-teamgenoot" aria-label="Permalink to &quot;Na een fout van een teamgenoot&quot;">​</a></h3><p><strong>Wat ze nodig hebben:</strong></p><ul><li>Snelle bevestiging</li><li>Toestemming om verder te gaan</li><li>Het vertrouwen dat je ze nog steeds vertrouwt.</li><li>Concentreer je op de volgende worp.</li></ul><p><strong>Wat te zeggen:</strong></p><ul><li>&quot;Geen probleem, de volgende.&quot;</li><li>&quot;Jammer dan, maar je krijgt de volgende.&quot;</li><li>&quot;We zitten er nog steeds middenin.&quot;</li><li><em>Soms is een knikje of een aai al genoeg.</em></li></ul><p><strong>Wat je NIET moet zeggen:</strong></p><ul><li>Niets (stilte voelt als oordeel)</li><li>&quot;Het is oké&quot; (kan afwijzend klinken)</li><li>Alles over wat er misging (niet nu)</li><li>Zichtbare frustratie (lichaamstaal is belangrijk)</li></ul><h3 id="wanneer-je-een-fout-maakt" tabindex="-1">Wanneer je een fout maakt <a class="header-anchor" href="#wanneer-je-een-fout-maakt" aria-label="Permalink to &quot;Wanneer je een fout maakt&quot;">​</a></h3><p><strong>Wat te doen:</strong></p><ul><li>Korte erkenning (&quot;Mijn excuses&quot;)</li><li>Verontschuldig je niet te vaak.</li><li>Maak geen excuses.</li><li>Reset en concentreer je op de volgende worp.</li><li>Vertrouw erop dat je teamgenoten je steunen.</li></ul><h3 id="spanning-binnen-het-team" tabindex="-1">Spanning binnen het team <a class="header-anchor" href="#spanning-binnen-het-team" aria-label="Permalink to &quot;Spanning binnen het team&quot;">​</a></h3><p>Als de spanning tijdens een wedstrijd oploopt:</p><ol><li>Erken dat het gebeurt</li><li>Haal even diep adem voordat je antwoordt.</li><li>Focus op het spel, niet op het conflict.</li><li>Pak het na de wedstrijd op de juiste manier aan.</li><li>Laat het je spel niet beïnvloeden</li></ol><h2 id="non-verbale-communicatie" tabindex="-1">Non-verbale communicatie <a class="header-anchor" href="#non-verbale-communicatie" aria-label="Permalink to &quot;Non-verbale communicatie&quot;">​</a></h2><p>Een groot deel van de teamcommunicatie is non-verbaal:</p><h3 id="positieve-signalen" tabindex="-1">Positieve signalen <a class="header-anchor" href="#positieve-signalen" aria-label="Permalink to &quot;Positieve signalen&quot;">​</a></h3><ul><li>Oogcontact</li><li>knikken</li><li>Duim omhoog</li><li>Ontspannen houding</li><li>Zich naar teamgenoten toe bewegen</li><li>Glimlachen (indien gepast)</li></ul><h3 id="negatieve-signalen-vermijd-deze" tabindex="-1">Negatieve signalen (vermijd deze) <a class="header-anchor" href="#negatieve-signalen-vermijd-deze" aria-label="Permalink to &quot;Negatieve signalen (vermijd deze)&quot;">​</a></h3><ul><li>Ogen rollen</li><li>Zich afwenden</li><li>Gekruiste armen</li><li>Zuchten</li><li>Hoofdschudden</li><li>Gespannen lichaamstaal</li></ul><p><strong>Onthoud dit:</strong> Je teamgenoten zien alles. Jouw lichaamstaal beïnvloedt hun zelfvertrouwen en prestaties.</p><h2 id="communicatievaardigheden-ontwikkelen" tabindex="-1">Communicatievaardigheden ontwikkelen <a class="header-anchor" href="#communicatievaardigheden-ontwikkelen" aria-label="Permalink to &quot;Communicatievaardigheden ontwikkelen&quot;">​</a></h2><h3 id="oefen-communicatie" tabindex="-1">Oefen communicatie <a class="header-anchor" href="#oefen-communicatie" aria-label="Permalink to &quot;Oefen communicatie&quot;">​</a></h3><p>Wacht niet tot de concurrentie communiceert:</p><ul><li>Oefen strategische discussies tijdens de training.</li><li>Geef elkaar regelmatig feedback.</li><li>Ontwikkel de teamtaal</li><li>Creëer een comfortabele sfeer door open en eerlijke gesprekken te voeren.</li></ul><h3 id="teamsignalen-ontwikkelen" tabindex="-1">Teamsignalen ontwikkelen <a class="header-anchor" href="#teamsignalen-ontwikkelen" aria-label="Permalink to &quot;Teamsignalen ontwikkelen&quot;">​</a></h3><p>Sommige teams ontwikkelen een soort steno:</p><ul><li>Handgebaren voor strategie</li><li>Codewoorden voor situaties</li><li>Korte zinnen met een gedeelde betekenis</li></ul><h3 id="regelmatige-check-ins" tabindex="-1">Regelmatige check-ins <a class="header-anchor" href="#regelmatige-check-ins" aria-label="Permalink to &quot;Regelmatige check-ins&quot;">​</a></h3><p>Buiten de wedstrijden om:</p><ul><li>Hoe werken we samen?</li><li>Wat gaat er goed?</li><li>Wat is er nou beter?</li><li>Zijn er nog zaken die we moeten aanpakken?</li></ul><h2 id="de-rol-van-de-kapitein" tabindex="-1">De rol van de kapitein <a class="header-anchor" href="#de-rol-van-de-kapitein" aria-label="Permalink to &quot;De rol van de kapitein&quot;">​</a></h2><p>Als uw team een aangewezen leider heeft:</p><p><strong>Verantwoordelijkheden van de kapitein:</strong></p><ul><li>Definitieve beslissing wanneer het team het oneens is.</li><li>De toon en energie bepalen</li><li>Het managen van teamdynamiek</li><li>Geconcentreerd blijven onder druk</li></ul><p><strong>Alle anderen:</strong></p><ul><li>Deel je perspectief</li><li>Steun de genomen beslissing.</li><li>Help de teamenergie te behouden.</li><li>Neem de verantwoordelijkheid voor je rol.</li></ul><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>Goede teams praten mét elkaar, niet óver elkaar. Ze communiceren met eerlijkheid, respect en een gezamenlijke inzet voor succes.</p></blockquote><p>Oefen communicatie zoals je werpen oefent. Het is een vaardigheid die verbetert door aandacht.</p>',68))])}]]);export{u as __pageData,c as default};
